const PAGE = 8192, HEADER = 24, ITEMPTR = 4, TUPHDR = 23;
function maxalign(n) { return Math.ceil(n / 8) * 8; }
const colData = 45;
const footprint = ITEMPTR + maxalign(TUPHDR + colData);
const perPage = Math.floor((PAGE - HEADER) / footprint);
const pages = Math.ceil(10000000 / perPage);
console.log(`footprint=${footprint} perPage=${perPage} pages=${pages}`);
